<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '../api/client'
import type { Coverage, StageCoverage } from '../api/contracts'
const lifecycle = ref<StageCoverage[]>([]), coverage = ref<Coverage | null>(null), error = ref(''), loading = ref(true)
onMounted(async () => { try { const [l, c] = await Promise.all([api.lifecycle(), api.coverage()]); lifecycle.value = l.stages; coverage.value = c.coverage } catch (e) { error.value = e instanceof Error ? e.message : '无法读取治理投影' } finally { loading.value = false } })
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">EVIDENCE-BACKED STAGE COVERAGE</p><h1>治理覆盖</h1><p>显示已记录阶段事实，不把“已配置”或阶段通过推断为 CI、审批、Review、外部诊断已经覆盖。</p></div></div><p v-if="error" class="data-warning">⚠ {{ error }}；未显示 Mock 或兼容覆盖率。</p><p v-else-if="loading" class="empty-state">正在读取治理投影…</p><section v-else class="governance-card"><div class="coverage-head"><b>阶段</b><b>已记录</b><b>未到达</b><b>不确定</b><b>五态计数</b></div><div v-for="stage in lifecycle" :key="stage.stage" class="coverage-row"><b>{{ stage.stage }}</b><span>{{ stage.recorded_runs }} / {{ stage.run_count }}</span><span>{{ stage.not_reached_runs }}</span><span>{{ stage.indeterminate_runs }}</span><span class="coverage-cell">P {{ stage.status_counts.passed }} · F {{ stage.status_counts.failed }} · U {{ stage.status_counts.unavailable }} · I {{ stage.status_counts.indeterminate }} · S {{ stage.status_counts.skipped }}</span></div></section><section v-if="coverage" class="governance-notes"><article><i>✓</i><div><b>{{ coverage.coverage_scope }}</b><p>{{ coverage.run_count }} 个 Run 由 {{ coverage.source }} 提供。</p></div></article><article><i>!</i><div><b>明确限制</b><p>{{ coverage.limitations.join(' ') }}</p></div></article></section></section></template>
